import 'dotenv/config';
import { readFileSync, readdirSync } from 'node:fs';
import { resolve } from 'node:path';
const runConfig = JSON.parse(readFileSync(resolve('config/run.config.json'), 'utf8'));
export function getAvailableEnvironments() { return readdirSync(resolve('test-data')).filter(file => file.endsWith('.json')).map(file => file.slice(0, -5)).sort(); }
export function getEnvironment() {
  const cli = process.argv.find(value => value.startsWith('--env='))?.slice(6);
  const value = cli ?? process.env.TEST_ENV ?? runConfig.environment;
  const available = getAvailableEnvironments();
  if (!available.includes(value)) throw new Error(`Unknown environment "${value}". Available: ${available.join(', ')}`);
  return value;
}
export function getRunConfig() { return runConfig; }
export function getTestData() { return JSON.parse(readFileSync(resolve('test-data', `${getEnvironment()}.json`), 'utf8')); }
export function getEnvironmentConfig() { const data = getTestData(); return { baseUrl: data.baseUrl ?? 'https://www.saucedemo.com', apiBaseUrl: data.apiBaseUrl ?? 'https://jsonplaceholder.typicode.com' }; }
